'use strict';

var pow = require( '@stdlib/math/base/special/pow' );
var sin = require( '@stdlib/math/base/special/sin' );
var brentq = require( './../lib' );

function f( x ) {
	return pow( x, 3 ) - ( 2.0 * x ) - 5.0;
}

var out = brentq( f, 2.0, 3.0, 100, 2e-12, 8.88e-16, [] );
console.log( 'f(x) = x^3 - 2x - 5' );
console.log( 'Root: %d', out.root );
console.log( 'f(root): %d', f( out.root ) );
console.log( 'Iterations: %d', out.iterations );

// Example with options
function g( x ) {
	return sin( x );
}

out = brentq( g, 3.0, 4.0, 100, 1e-4, 8.88e-16, [] );
console.log( '\nf(x) = sin(x)' );
console.log( 'Root matching 3.14 on [3, 4] with xtol 1e-4: %d', out.root );
console.log( 'f(root): %d', g( out.root ) );
console.log( 'Iterations: %d', out.iterations );
